--liquibase formatted sql

--changeset creditsai:005-create-credit-number-sequence
CREATE SEQUENCE credit_number_seq START WITH 1 INCREMENT BY 1;
--rollback DROP SEQUENCE credit_number_seq;

--changeset creditsai:005-create-credits
-- credit_number is generated by the database on insert: CR-{year}-{6-digit sequence}, e.g. CR-2026-000123.
CREATE TABLE credits (
    id                     BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    credit_number          VARCHAR(20)   NOT NULL UNIQUE
        DEFAULT ('CR-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('credit_number_seq')::text, 6, '0')),
    client_id              BIGINT        NOT NULL REFERENCES clients (id),
    type                   VARCHAR(20)   NOT NULL CHECK (type IN ('CONSUMER', 'MORTGAGE', 'AUTO', 'BUSINESS')),
    amount                 NUMERIC(12,2) NOT NULL CHECK (amount > 0),
    currency               VARCHAR(3)    NOT NULL CHECK (currency IN ('EUR', 'USD', 'CHF')),
    interest_rate          NUMERIC(7,4)  NOT NULL CHECK (interest_rate >= 0),
    start_date             DATE          NOT NULL,
    end_date               DATE          NOT NULL,
    term_months            INTEGER       NOT NULL CHECK (term_months >= 1),
    monthly_payment        NUMERIC(12,2) NOT NULL,
    has_collateral         BOOLEAN       NOT NULL,
    collateral_value       NUMERIC(12,2) CHECK (collateral_value > 0),
    collateral_description VARCHAR(500),
    status                 VARCHAR(10)   NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE')),
    archived               BOOLEAN       NOT NULL DEFAULT false,
    archived_at            TIMESTAMPTZ,
    created_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_credits_end_after_start CHECK (end_date > start_date),
    CONSTRAINT ck_credits_collateral CHECK (
        (has_collateral AND collateral_value IS NOT NULL AND collateral_description IS NOT NULL)
        OR (NOT has_collateral AND collateral_value IS NULL AND collateral_description IS NULL))
);
--rollback DROP TABLE credits;

--changeset creditsai:005-create-credits-client-index
CREATE INDEX idx_credits_client_id ON credits (client_id);
--rollback DROP INDEX idx_credits_client_id;

--changeset creditsai:005-create-credits-archived-index
CREATE INDEX idx_credits_archived ON credits (archived);
--rollback DROP INDEX idx_credits_archived;
